 * Layouts call iconSprite() once inside <body>.
 */
if (!function_exists('icon')) {
    function icon(string $name, string $class = ''): string {
        $cls = trim('ico ' . $class);
        return '<svg class="' . $cls . '" aria-hidden="true"><use href="#i-' . $name . '"/></svg>';
    }
}
if (!function_exists('lakunAsset')) {
    /** Asset URL with a cache-busting version from the file's mtime. */
    function lakunAsset(string $path): string {
        $file = dirname(__DIR__, 3) . '/' . ltrim($path, '/');
        $v = is_file($file) ? filemtime($file) : '1';
        return APP_URL . '/' . ltrim($path, '/') . '?v=' . $v;
    }
}
